// portTarget is what a click on a port row opens: its edit form, or the
// identity check first (editing a port takes sudo), or nothing below admin.
func portTarget(d ServiceData, p PortRow) string {
	switch {
	case d.CanAdmin && d.SudoActive:
		return "#port-" + p.ID
	case d.CanAdmin:
		return "#sudo-dialog"
	}
	return ""
}

// portField fills the port form: the port being edited, or for a new one
// the service's own port as the container port.
func portField(p *PortRow, which string, servicePort int64) string {
	switch {
	case p != nil && which == "host":
		return strconv.FormatInt(p.HostPort, 10)
	case p != nil:
		return strconv.FormatInt(p.ContainerPort, 10)
	case which == "container":
		return portValue(servicePort)
	}
	return ""
}

// portIPs fills the IPs field: the port's own, or the viewer's IP for a new
// one.
func portIPs(p *PortRow, clientIP string) string {
	if p != nil {
		return p.IPs
	}
	return clientIP
}

